```yaml
- ansible.builtin.wait_for: {timeout: 300}
  delegate_to: localhost
- ansible.builtin.wait_for: {port: 8000, delay: 10}
- ansible.builtin.wait_for: {host: 0.0.0.0, port: 8000, state: drained, exclude_hosts: 10.2.1.2}
- ansible.builtin.wait_for: {path: /var/log/syslog, search_regex: 'tomcat [u]p'}
- ansible.builtin.wait_for: {path: /tmp/foo, search_regex: 'completed (?P<task>\w+)'}
  register: waitfor   # waitfor.match_groupdict.task
- ansible.builtin.wait_for: {path: /proc/3466/status, state: absent}
- ansible.builtin.wait_for:
    port: 22
    host: '{{ (ansible_ssh_host|default(ansible_host))|default(inventory_hostname) }}'
    search_regex: OpenSSH
    delay: 10
  delegate_to: localhost
```
